// Unlisted event page. The token is the secret. This route is not linked from
// directories. RSVP requires an account and does not offer plus-ones.
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, View } from 'react-native';
import { router, Stack, useFocusEffect, useLocalSearchParams } from 'expo-router';
import { PublicEventScreen } from '../../../components/public-event-screen';
import { Button, EmptyState, ErrorText, Page } from '../../../components/ui';
import { getEventJoinDetails, getUnlistedEvent, myEventRsvp, type EventJoinDetails } from '../../../lib/events';
import { unlistedAttendPath } from '../../../lib/event-visibility';
import { rememberReturnPath } from '../../../lib/auth';
import { trackEventPageView } from '../../../lib/analytics';
import { useSession } from '../../../lib/session';
import { colors } from '../../../lib/theme';
import type { PublicEvent } from '../../../lib/types';

export default function UnlistedEventPage() {
  const raw = useLocalSearchParams<{ token: string }>().token;
  const token = Array.isArray(raw) ? raw[0] : raw;
  const { userId, loading } = useSession();
  const [e, setE] = useState<PublicEvent | null | undefined>(undefined);
  const [join, setJoin] = useState<EventJoinDetails | null>(null);
  const [going, setGoing] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    if (!token) { setE(null); return; }
    let live = true;
    setE(undefined); setErr(null);
    getUnlistedEvent(token).then((row) => { if (live) setE(row); }).catch((x) => {
      if (live) { setErr(x?.message ?? 'Could not load this event.'); setE(null); }
    });
    return () => { live = false; };
  }, [token]);

  useFocusEffect(useCallback(() => {
    const eventId = e?.id;
    if (eventId) trackEventPageView(eventId, 'public');
  }, [e?.id]));

  useFocusEffect(useCallback(() => {
    const eventId = e?.id;
    if (!eventId || !userId) { setJoin(null); setGoing(false); return; }
    let live = true;
    Promise.all([getEventJoinDetails(eventId), myEventRsvp(eventId, userId)]).then(([details, rsvp]) => {
      if (!live) return;
      setJoin(details);
      setGoing(rsvp);
    }).catch(() => { if (live) { setJoin(null); setGoing(false); } });
    return () => { live = false; };
  }, [e?.id, userId]));

  const login = () => {
    if (!token) return;
    const next = `/e/u/${token}`;
    rememberReturnPath(next);
    router.push(`/sign-in?next=${encodeURIComponent(next)}`);
  };
  const attend = () => { if (token) router.push(unlistedAttendPath(token)); };
  const openInApp = () => { if (e) router.push(`/events/${e.id}`); };

  if (e === undefined && !err) return <View style={{ flex: 1, justifyContent: 'center' }}><ActivityIndicator color={colors.navy} /></View>;
  if (err) return <Page><ErrorText>{err}</ErrorText></Page>;
  if (!e || !token) return (
    <Page>
      <Stack.Screen options={{ title: 'Event' }} />
      <EmptyState icon="calendar-outline" title="Event not found" body="This link doesn’t open an event."
        action={!loading ? <Button small variant="neutral" title="Sign in" onPress={login} /> : undefined} />
    </Page>
  );

  return (
    <PublicEventScreen event={{ ...e, visibility: 'hidden' }} userId={userId} sessionLoading={loading}
      going={going} join={join} application={null}
      onAttend={attend} onApply={attend} onLogin={login} onOpenInApp={openInApp} />
  );
}
